import {Row, Col,Image, Container, Form, Button} from 'react-bootstrap'
import {useState} from 'react'
import {useNavigate} from 'react-router-dom'
function LogIn() {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');

        try{
            const response = await fetch(
                `http://localhost:9999/account?username=${username}&password=${password}`
            );
            const data = await response.json();

            if(data.length > 0){
                
            }
        }catch (err){
            setError('Không thể kết nối tới server');
        }
    }
  return (
    <>
        <Row>
            <h1 className="text-center text-primary mb-3 mt-3">Ôn Thi Trắc Nhiệm Bằng Lái Xe Máy</h1>
        </Row>
        <Row>
            <Col md={6}>
                <Image src='anhthi.png' alt="Description of the image" style={{width: '100%', height: '96%'}}/>
            </Col>
            <Col md={6}>
                
                    <h4 className='text-center'>Đăng nhập</h4>
                    <Container>
                    <Form>
                        <p>Tên đăng nhập</p>
                        <Form.Control className='form-control' placeholder="Nhập tên đăng nhập" value='username'></Form.Control>
                        <p className='mt-2'>Mật khẩu</p>
                        <Form.Control className='form-control' placeholder="Nhập mật khẩu" value='password'></Form.Control>
                        <Button className="btn btn-primary mt-3" type='submit'>Đăng nhập</Button>
                    </Form>
                    </Container>
            </Col>
        </Row>
    </>
  )
}

export default LogIn
